def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chair_patches = image_patch.find("chair")
    cat_patches = image_patch.find("cat")
    if not chair_patches or not cat_patches:
        return image_patch
    for chair in chair_patches:
        for cat in cat_patches:
            if chair.overlaps_with(cat.left, cat.lower, cat.right, cat.upper) and chair.is_in_front_of(cat):
                return chair
    return chair_patches[0] if chair_patches else cat_patches[0]

